on conflict (card_id, catalog_version) do update set
  source_number = excluded.source_number,
  category = excluded.category,
  title_original = excluded.title_original,
  description_original = excluded.description_original,
  illustration_idea_original = excluded.illustration_idea_original,
  image_path = excluded.image_path,
  source_sheet = excluded.source_sheet,
  effect_status = excluded.effect_status;

commit;

-- Expected result: 180 rows total, 30 in each category.
select
  category,
  count(*) as cards
from public.card_catalog
where catalog_version = 'v1'
group by category
order by case category
  when 'roles' then 1
  when 'skills' then 2
  when 'baggage' then 3
  when 'vulnerabilities' then 4
  when 'crises' then 5
  when 'actions' then 6
  else 99
end;

select count(*) as total_cards
from public.card_catalog
where catalog_version = 'v1';
